-- Schema v26 (PostgreSQL dialect): tickets — the durable work-order layer that
-- sits between a conversation turn and the experts/subagents that carry it out.
--
-- Mirrors 026_tickets.sql with PostgreSQL types:
--   INTEGER PRIMARY KEY AUTOINCREMENT -> BIGINT GENERATED BY DEFAULT AS IDENTITY
--   INTEGER timestamps                -> BIGINT (Unix seconds)
--
-- Additive only. `thread_id` is a soft foreign key: threads live in the engine
-- checkpoint store, not in this database.

CREATE TABLE IF NOT EXISTS tickets (
  id                BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  ticket_id         TEXT NOT NULL UNIQUE,
  owner_user_id     BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  agent_id          TEXT NOT NULL,
  thread_id         TEXT,
  title             TEXT NOT NULL,
  goal              TEXT NOT NULL DEFAULT '',
  stage             TEXT NOT NULL DEFAULT 'working/queued',
  priority          INTEGER NOT NULL DEFAULT 0,
  assignment_kind   TEXT NOT NULL DEFAULT 'expert',
  assignee_id       TEXT,
  open_attention    INTEGER NOT NULL DEFAULT 0,
  attention_reason  TEXT,
  latest_report     TEXT,
  delivery_failed   INTEGER NOT NULL DEFAULT 0,
  created_at        BIGINT NOT NULL,
  updated_at        BIGINT NOT NULL,
  started_at        BIGINT,
  ended_at          BIGINT
);

CREATE INDEX IF NOT EXISTS idx_tickets_owner_stage
  ON tickets(owner_user_id, stage);

CREATE INDEX IF NOT EXISTS idx_tickets_thread
  ON tickets(thread_id);

CREATE INDEX IF NOT EXISTS idx_tickets_agent
  ON tickets(agent_id);

CREATE INDEX IF NOT EXISTS idx_tickets_updated
  ON tickets(owner_user_id, updated_at DESC);

CREATE TABLE IF NOT EXISTS ticket_events (
  id           BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  ticket_id    TEXT NOT NULL REFERENCES tickets(ticket_id) ON DELETE CASCADE,
  kind         TEXT NOT NULL,
  actor        TEXT,
  summary      TEXT NOT NULL DEFAULT '',
  payload_json TEXT NOT NULL DEFAULT '{}',
  created_at   BIGINT NOT NULL
);

CREATE INDEX IF NOT EXISTS idx_ticket_events_ticket
  ON ticket_events(ticket_id, created_at);

UPDATE _schema_version SET version = 26;
